function hasAdminPermission(user,permission){
 if(user?.role==='super_admin')return true
 const permissions=Array.isArray(user?.permissions)?user.permissions:(DEFAULT_NAV_PERMISSIONS[user?.role]||[])
 return permissions.includes(permission)
}
function canAccessAdminPath(path,user){
 if(user?.role==='super_admin')return true
 const rawPath=String(path||''),normalizedPath=rawPath.split('?')[0]
 const required=rawPath.includes('new=1')?['products.write']:(NAV_REQUIRED_PERMISSIONS[normalizedPath]||[])
 return required.every(permission=>hasAdminPermission(user,permission))
}
