  <div className="admin-dash-heading"><div><span className="eyebrow">STORE OVERVIEW</span><h1>Dashboard</h1><p>Welcome back, {shortName}! 👋</p></div><div className="admin-dash-heading-actions"><button type="button" className="admin-dash-refresh" onClick={load} disabled={loading}><RefreshCw size={15}/> {loading?'Loading…':'Refresh data'}</button><label className="admin-dash-range"><span>Analytics</span><select value={days} onChange={e=>setDays(Number(e.target.value))}><option value={7}>Last 7 days</option><option value={30}>Last 30 days</option><option value={90}>Last 90 days</option></select></label></div></div>
  {error&&<p className="api-notice">{error}</p>}
  <section className="admin-dash-stats">
   {[['Total Orders',stats.orders,ShoppingCart,'orders','All customer orders'],['Total Customers',stats.customers,Users,'customers','Registered accounts'],['Total Revenue',money(stats.sales),BarChart3,'revenue','Delivered order revenue'],['Total Products',stats.products,Package,'products','Products in catalogue']].map(([label,value,Icon,tone,caption])=><article className={'admin-dash-stat '+tone} key={tone}><div className="admin-dash-stat-top"><span className="admin-dash-stat-icon"><Icon size={23}/></span><span className="admin-dash-stat-caption">{caption}</span></div><h3>{value}</h3><p>{label}</p></article>)}
  </section>
